scripts.script:
if ((args.move.type === 'basic' && args.move.id !== 'opportunity-attack')) return;
const shalu = system.resources.shalu.value || 0;
const shanie = system.resources.shanie || 0;
if (shalu > 0 || shanie > 0) {
    args.output.damage += 10;
    args.output.bonusDesc.push("止刑功 +10");
}

if ((args.move.type === 'basic' && args.move.id !== 'opportunity-attack')) return;
const shalu = system.resources.shalu.value || 0;
const shanie = system.resources.shanie || 0;
if (shalu > 0 || shanie > 0) {
    args.output.damage += 15;
    args.output.bonusDesc.push("止刑功 +15");
}

const tShalu = args.target.system?.resources?.shalu?.value || 0;
const tShanie = args.target.system?.resources?.shanie || 0;
if (tShalu > 0 || tShanie > 0) {
    args.flags.grantFeint += 2;
}

const roll = await actor.rollAttributeTest("dongcha", { skipDialog: true });
const val = roll.total;
const sourceEffect = thisItem.effects.getName("断案值");
if (sourceEffect) {
    const effData = sourceEffect.toObject();
    delete effData._id;
    effData.origin = thisItem.uuid;
    effData.changes[0].value = String(val);
    effData.changes[1].value = String(val);
    effData.flags["xjzl-system"].duanVal = val;
    await game.xjzl.api.effects.addEffect(actor, effData);
    ui.notifications.info(`【罪恶断】获得 ${val} 点断案值`);
}

const roll = await actor.rollAttributeTest("dongcha", { skipDialog: true });
const val = roll.total + 5;
const sourceEffect = thisItem.effects.getName("断案值");
if (sourceEffect) {
    const effData = sourceEffect.toObject();
    delete effData._id;
    effData.origin = thisItem.uuid;
    effData.changes[0].value = String(val);
    effData.changes[1].value = String(val);
    effData.flags["xjzl-system"].duanVal = val;
    await game.xjzl.api.effects.addEffect(actor, effData);
    ui.notifications.info(`【罪恶断】获得 ${val} 点断案值 (含圆满+5)`);
}

if ((args.move.type !== 'basic' || args.move.id === 'opportunity-attack')) {
    const val = thisEffect.getFlag('xjzl-system', 'duanVal') || 0;
    args.output.damage += val;
    args.output.bonusDesc.push(`断案值预演 +${val}`);
}

if ((args.move.type !== 'basic' || args.move.id === 'opportunity-attack')) {
    const val = thisEffect.getFlag('xjzl-system', 'duanVal') || 0;
    const confirm = await foundry.applications.api.DialogV2.confirm({
        window: { title: "断案裁决" },
        content: `<p>当前具备 <b>${val}</b> 点断案威力。</p><p>是否在此次出招中消耗断案值？一旦使用该状态即会移除。</p>`,
        yes: { label: "消耗加伤", icon: "fas fa-check" },
        no: { label: "保留状态", icon: "fas fa-times" }
    });
    if(confirm) {
        ui.notifications.info("已消耗断案值增强招式！");
        await thisEffect.delete();
    } else {
        args.flags.damageResult.damage -= val;
        args.flags.damageResult.breakdown += `\n- 放弃消耗断案值 (-${val})`;
    }
}

if ((args.move.type !== 'basic' || args.move.id === 'opportunity-attack')) {
    const tHuti = args.target.system.resources.huti || 0;
    if (tHuti > 0) {
        await args.target.update({ "system.resources.huti": Math.max(0, tHuti - 20) });
        ui.notifications.info(`破罡神功：消融了 ${Math.min(20, tHuti)} 点护体！`);
    }
}

const mpSpent = args.costConsumed?.mp || 0;
if (mpSpent > 0) {
    const heal = mpSpent * 1;
    await actor.applyHealing({ amount: heal, type: "hp", showScrolling: true });
    const msg = `<div class="xjzl-chat-card" style="margin-left: 6px;"><div style="border-left: 3px solid #27ae60; background: rgba(39,174,96,0.1); padding: 5px 8px;"><div style="font-weight:bold; color:#1e8449;"><i class="fas fa-yin-yang"></i> 界元真气流转</div><div style="font-size:0.9em; color:#555; margin-top:3px;">消耗 ${mpSpent} 点内力，生生不息转化为 <span style="color:green; font-weight:bold;">${heal}</span> 点气血。</div></div></div>`;
    ChatMessage.create({ speaker: ChatMessage.getSpeaker({actor: actor}), content: msg });
}

const mpSpent = args.costConsumed?.mp || 0;
if (mpSpent > 0) {
    const heal = mpSpent * 2;
    await actor.applyHealing({ amount: heal, type: "hp", showScrolling: true });
    const msg = `<div class="xjzl-chat-card" style="margin-left: 6px;"><div style="border-left: 3px solid #27ae60; background: rgba(39,174,96,0.1); padding: 5px 8px;"><div style="font-weight:bold; color:#1e8449;"><i class="fas fa-yin-yang"></i> 界元真气流转</div><div style="font-size:0.9em; color:#555; margin-top:3px;">消耗 ${mpSpent} 点内力，生生不息转化为 <span style="color:green; font-weight:bold;">${heal}</span> 点气血。</div></div></div>`;
    ChatMessage.create({ speaker: ChatMessage.getSpeaker({actor: actor}), content: msg });
}

const mpSpent = args.costConsumed?.mp || 0;
if (mpSpent > 0) {
    const heal = mpSpent * 3;
    await actor.applyHealing({ amount: heal, type: "hp", showScrolling: true });
    const msg = `<div class="xjzl-chat-card" style="margin-left: 6px;"><div style="border-left: 3px solid #27ae60; background: rgba(39,174,96,0.1); padding: 5px 8px;"><div style="font-weight:bold; color:#1e8449;"><i class="fas fa-yin-yang"></i> 界元真气流转</div><div style="font-size:0.9em; color:#555; margin-top:3px;">消耗 ${mpSpent} 点内力，生生不息转化为 <span style="color:green; font-weight:bold;">${heal}</span> 点气血。</div></div></div>`;
    ChatMessage.create({ speaker: ChatMessage.getSpeaker({actor: actor}), content: msg });
}
